\draw (N2) -- (E3) node[midway, above, fill=white, font=\small] {$0.7$};
\draw (N2) -- (E4) node[midway, below, fill=white, font=\small] {$0.3$};
\node[fill=white, inner sep=2pt] at (N1) {$W$};
\node[fill=white, inner sep=2pt] at (N2) {$F$};
\node[right] at (E1) {$W\quad 0.49$};
\node[right] at (E2) {$F\quad 0.21$};
\node[right] at (E3) {$W\quad 0.21$};
